kernel_policy.configuration:
# Generated by deploy/connections.py. SYN packets, including retries, are counted.
# Only this explicit listener/interface is policed; existing connections pass.
table inet zhtps_connections {
    counter syn_attempts { }
    counter syn_over_limit { }
    counter syn_resets { }
    counter syn_drops { }
    chain reject_connection {
        limit rate 1000/second burst 32 packets counter name syn_resets reject with tcp reset
        counter name syn_drops drop
    }
    chain incoming {
        type filter hook prerouting priority -300; policy accept;
        iifname "lo" ip daddr 127.0.0.1 tcp dport 8080 tcp flags & (syn | ack) == syn counter name syn_attempts limit rate over 10000/second burst 384 packets counter name syn_over_limit jump reject_connection
    }
}

